import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"15、【謙】 艮下坤上","description":"子夏易傳 - 15、【謙】 艮下坤上","frontmatter":{"title":"15、【謙】 艮下坤上","description":"子夏易傳 - 15、【謙】 艮下坤上"},"headers":[],"relativePath":"classics/zixia/017.md","filePath":"classics/zixia/017.md"}'),i={name:"classics/zixia/017.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_15、【謙】-艮下坤上" tabindex="-1">15、【謙】 艮下坤上 <a class="header-anchor" href="#_15、【謙】-艮下坤上" aria-label="Permalink to “15、【謙】 艮下坤上”">​</a></h1><p>卦辭：謙，亨。君子有終。</p><p>彖曰：謙，亨。天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙。鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可踰，君子之終也。</p><p>子夏：陽，天也，而下其隂，是以謙。無不通。君子所以保終也。天之道，寒暑日月也。盈則虧之，損則益之。地之道，山川丘陵谷也。髙則傾之，卑則受之。鬼神依人，謙則福之，盈則禍之。人道惡盈，盈則慢之，以人惡已。謙則下人，故人好也。尊而謙之，益光大矣。卑而謙之，人莫之踰。君子所以保終也。</p><p>象曰：地中有山，謙。君子以裒多益寡，稱物平施。</p><p>子夏：山下於地，而得地中，謙也。君子謙以下人，得人心也。多者損己，以聚之寡者減己，以益之稱物而平施。不失其常乃平也。</p><p>初六，謙謙君子，用涉大川，吉。</p><p>象曰：謙謙君子，卑以自牧也。</p><p>子夏：柔以處下，謙之謙也。君子用謙於初，自養其德，雖涉難而吉也。</p><p>六二，鳴謙，貞吉。</p><p>象曰：鳴謙貞吉，中心得也。</p><p>子夏：陽者眾隂之所求也。二承而親之，旣得於心，聲以發外，謙而鳴之，辭也。守中而不敢自大，得正之吉也。</p><p>九三，勞謙君子，有終吉。</p><p>象曰：勞謙君子，萬民服也。</p><p>子夏：居下之上，為眾之，則勤於正，眾雖勞，而謙厚之至也。謙以保位，萬民服也，故得保其終，吉矣。</p><p>六四，無不利，撝謙。</p><p>象曰：無不利，撝謙。不違則也。</p><p>子夏：謙以在位，不僭不偪，不違其則者也。以之奉五，而待於三，奉事得宜，指撝皆從，無不利也。謙敬之利，道之然也。</p><p>六五，不富以其鄰，利用侵伐，無不利。</p><p>象曰：利用侵伐，徵不服也。</p><p>子夏：柔居上位，止而順之，謙也。柔之過，盜之心生，故至用師也。居尊而著於謙，得眾之道也，故不待富鄰而利以侵伐也。</p><p>上六，鳴謙，利用行師，徵邑國。</p><p>象曰：鳴謙，志未得也。可用行師徵邑國也。</p><p>子夏：上雖應三，二近相與，故中心未得也。徒聲鳴而已。然正應無爭，辭謙無怨，是以外助也。分眾受命，才堪徵邑國而已，非不利者也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
